lEffectsAllowed !== false) throw new TypeError(\\\"threeModule contract 漂移\\\"); const serialized = JSON.stringify(raw).toLowerCase(); for (const forbidden of [\\\"mobile\\\", \\\"openid\\\", \\\"email\\\", \\\"address\\\", \\\"contactvalue\\\", \\\"providerpayload\\\"]) if (serialized.includes(forbidden)) throw new TypeError(\\\"threeModule 泄露 PII/provider payload\\\"); return { schemaVersion: THREE_MODULE_CLOSURE_SCHEMA_VERSION, tenant, module, evaluatedAt: timestamp(raw.evaluatedAt, \\\"threeModule.evaluatedAt\\\"), atomicSkillIds: raw.atomicSkillIds.map((item) => boundedText(item, \\\"threeModule.skill\\\", 200)), logicId: boundedText(raw.logicId, \\\"threeModule.logicId\\\", 200), primaryColleague: boundedText(raw.primaryColleague, \\\"threeModule.primary\\\", 80), collaboratorColleagues: raw.collaboratorColleagues.map((item) => boundedText(item, \\\"threeModule.collaborator\\\", 80)), latestClosure: raw.latestClosure === null ? null : parseThreeModuleClosure(raw.latestClosure, tenant, module), latestUsage: raw.latestUsage === null ? null : parseThreeModuleUsage(raw.latestUsage, tenant), latestEffect: raw.latestEffect === null ? null : parseThreeModuleEffect(raw.latestEffect, tenant), latestHandoff: raw.latestHandoff === null ? null : parseThreeModuleHandoff(raw.latestHandoff, tenant), blockers: raw.blockers.map((item) => boundedText(item, \\\"threeModule.blocker\\\", 200)), allowedCommands: [...THREE_MODULE_COMMANDS], handoffConsumeAllowed: false, memoryPromotionAllowed: false, externalEffectsAllowed: false }; }\\nEXACT EXISTING TEST\\nimport { describe, expect, it } from \\\"vitest\\\";\\nimport { EcommerceWorkshopClient } from \\\"./client\\\";\\n\\nconst payload = { schemaVersion: \\\"aos.ecommerce-workshop.three-module-closure/v1\\\", tenant: { orgId: \\\"org-org\\\", projectId: \\\"dev-project\\\" }, module: \\\"creator\\\", evaluatedAt: \\\"2026-08-25T09:00:00Z\\\", atomicSkillIds: [\\\"creator-batch-prepare\\\", \\\"creator-lane-reconcile\\\"], logicId: