ad.tenant, bindingId: \\\"usage-binding-1\\\", revision: 1, closureRef: exact, usageReceiptRef: { ...exact, resourceType: \\\"UsageReceipt\\\", resourceId: \\\"usage-1\\\", receiptId: \\\"usage-1\\\" }, lineageId: \\\"server-lineage\\\", quality: \\\"unknown\\\", quantity: 0, unit: \\\"tokens\\\", adjustmentTotal: 0, settlement: \\\"unknown\\\", contentHash: \\\"b\\\".repeat(64), boundAt: payload.evaluatedAt }; await expect(client({ ...payload, latestUsage }).getThreeModuleClosureContributionView(\\\"creator\\\")).rejects.toThrow(/伪 0/); });\\n  it(\\\"拒绝 PII 或 provider payload 泄漏\\\", async () => { await expect(client({ ...payload, blockers: [\\\"mobile\\\"] }).getThreeModuleClosureContributionView(\\\"creator\\\")).rejects.toThrow(/PII/); });\\n});\\n\\nPROPOSED EXACT FUNCTION DESIGN\\nexport function parseThreeModuleClosureContributionView(value: unknown, expectedModule?: ThreeModuleId, expectedTenant?: WorkshopTenant): ThreeModuleClosureContributionViewResponse { const raw = record(value, \\\"threeModule\\\"); exact(raw, [\\\"schemaVersion\\\", \\\"tenant\\\", \\\"module\\\", \\\"evaluatedAt\\\", \\\"atomicSkillIds\\\", \\\"logicId\\\", \\\"primaryColleague\\\", \\\"collaboratorColleagues\\\", \\\"latestClosure\\\", \\\"latestUsage\\\", \\\"latestEffect\\\", \\\"latestHandoff\\\", \\\"blockers\\\", \\\"allowedCommands\\\", \\\"handoffConsumeAllowed\\\", \\\"memoryPromotionAllowed\\\", \\\"externalEffectsAllowed\\\"], \\\"threeModule\\\"); const tenant = parseTenant(raw.tenant); const module = enumValue(raw.module, THREE_MODULE_IDS, \\\"threeModule.module\\\"); if (raw.schemaVersion !== THREE_MODULE_CLOSURE_SCHEMA_VERSION || (expectedModule && module !== expectedModule) || (expectedTenant && (tenant.orgId !== expectedTenant.orgId || tenant.projectId !== expectedTenant.projectId)) || !Array.isArray(raw.atomicSkillIds) || !raw.atomicSkillIds.length || !Array.isArray(raw.collaboratorColleagues) || !Array.isArray(raw.blockers) || !Array.isArray(raw.allowedCommands) |